#!/usr/bin/env bash
# Documentation : « Membres et collaboration » en six chapitres (le compte et le profil, l'avatar, les documents,
# les groupes, les espaces, les demandes) ; plages recalées. Prérequis : apply-fix-membres.sh et apply-docs-avatars.sh.
# Aucune migration. Usage (racine du repo) : bash apply-docs-membres.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/membres/les-groupes.mdx" 2>/dev/null | grep -qF "Une hiérarchie qui transmet ses droits vers le bas"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Destinataire ou groupe inconnu" "packages/backend/src/modules/memberDocuments/router.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-membres.sh"; exit 1; }
grep -qF "Les avatars n’en font pas partie" "apps/web/content/docs/dev/stockage/lire-l-arbre.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-avatars.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/api/fabriquer-une-procedure.mdx" "apps/web/content/docs/dev/api/gerer-les-erreurs.mdx" "apps/web/content/docs/dev/api/maitriser-la-sortie.mdx" "apps/web/content/docs/dev/api/proteger-une-procedure.mdx" "apps/web/content/docs/dev/api/valider-l-entree.mdx" "apps/web/content/docs/dev/auth/la-session-dans-le-backend.mdx" "apps/web/content/docs/dev/contenu/un-contenu-ecrit-par-un-membre.mdx" "apps/web/content/docs/dev/membres/demandes.mdx" "apps/web/content/docs/dev/membres/documents-des-membres.mdx" "apps/web/content/docs/dev/membres/espaces-collaboratifs.mdx" "apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx")
EXPECT=("b73d67f08ff9:apps/web/content/docs/dev/api/fabriquer-une-procedure.mdx" "57035a7527da:apps/web/content/docs/dev/api/gerer-les-erreurs.mdx" "cbcd7c978885:apps/web/content/docs/dev/api/maitriser-la-sortie.mdx" "9c54e02f11bb:apps/web/content/docs/dev/api/proteger-une-procedure.mdx" "5e86d252e4f7:apps/web/content/docs/dev/api/valider-l-entree.mdx" "79a63496f517:apps/web/content/docs/dev/auth/la-session-dans-le-backend.mdx" "080c6954faf4:apps/web/content/docs/dev/contenu/un-contenu-ecrit-par-un-membre.mdx" "18c0441ce8ca:apps/web/content/docs/dev/membres/demandes.mdx" "63fb3db4ae1e:apps/web/content/docs/dev/membres/documents-des-membres.mdx" "77bab262d55c:apps/web/content/docs/dev/membres/espaces-collaboratifs.mdx" "1306347228fa:apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/content/docs/dev/membres/l-avatar.mdx" "apps/web/content/docs/dev/membres/les-groupes.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Une hiérarchie qui transmet ses droits vers le bas" "apps/web/content/docs/dev/membres/les-groupes.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/membres"
