# Table de l'index : ligne « Membres et collaboration », quel que soit son texte actuel.
F=apps/web/content/docs/dev/index.mdx
if ! git diff --quiet HEAD -- "$F"; then echo "❌ $F a des modifications non commitées"; restore; exit 1; fi
MODIFIED+=("$F")
python3 - "$F" <<'PY2'
import re, sys
p = sys.argv[1]; s = open(p, encoding="utf-8").read()
new = "[\"Membres et collaboration\",\"En six chapitres : le compte et le profil (un mot de passe qui ne va qu’au membre, un profil scellé, un compte qui part sans rien laisser) ; l’avatar (un circuit à part, représenter n’est pas poser, hors de la bibliothèque) ; les documents des membres (concerner et pouvoir ouvrir, lu ou non lu) ; les groupes (un arbre dont la racine ne bouge pas, des droits qui descendent) ; les espaces collaboratifs (tout se déduit du chemin, un dépôt devient document du groupe) ; les demandes.\",\"rédigée\"]"
s2, n = re.subn(r'\["Membres et collaboration","[^"]*","[^"]*"\]', lambda m: new, s)
assert n == 1, n
open(p, "w", encoding="utf-8").write(s2)
PY2
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
docs(membres): six chapitres

- Le compte et le profil : user.create pas à pas, le mot de passe généré et ce qui le garde au membre,
  la première connexion et la relecture de session, la server action scellée, le nom affiché,
  user.delete et ce qu'un compte laisse (ou non) derrière lui
- L'avatar (nouveau) : pas un média comme les autres, l'envoi signé, ce que vérifie le serveur, la
  route qui ne sert que des avatars, la version par membre, représenter n'est pas poser, hors de la
  bibliothèque
